import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"ADR-095 — Eccentric planets, the JPL reference and vector v∞ in the shared transfer model","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-095.md","filePath":"adr/ADR-095.md"}'),s={name:"adr/ADR-095.md"};function n(d,e,c,i,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-095-—-eccentric-planets-the-jpl-reference-and-vector-v∞-in-the-shared-transfer-model" tabindex="-1">ADR-095 — Eccentric planets, the JPL reference and vector v∞ in the shared transfer model <a class="header-anchor" href="#adr-095-—-eccentric-planets-the-jpl-reference-and-vector-v∞-in-the-shared-transfer-model" aria-label="Permalink to &quot;ADR-095 — Eccentric planets, the JPL reference and vector v∞ in the shared transfer model&quot;">​</a></h1><blockquote><p>Status · Accepted · 2026-11-07 · Operator-directed (&quot;align with the JPL as a reference … validate all the clients using that equation&quot;) · supersedes the &quot;all planets use circular <code>a</code>&quot; line of <strong>ADR-028</strong> §Schema additions · builds on <strong>ADR-026</strong> (multi-destination grid) and <strong>ADR-085</strong> §D2 (vector arrival v∞)</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>destinationPos</code> (mission-arc) and <code>destinationHelioXY</code> (lambert-grid) place every body on the mean-element model shared by <code>/fly</code>, the <code>/plan</code> porkchops (precomputed and worker), the Lab porkchop and the moon porkchops. ADR-028 kept the planets circular so the short-way Lambert grid converged and the old goldens held. Checked against the JPL Keplerian ephemeris (<code>physics/ephemeris</code>, the one the sky views and the mission blueprints use), 1970–2035:</p><ul><li>circles put Mercury up to 24° from its real longitude, Mars 10.8°, the giants 5–6°, Earth 1.9°; <code>/fly</code> pins every labelled flyby waypoint to these positions, so flybys sat off the real geometry;</li><li>the grids counted days from 2026-01-01 but placed planets with J2000 elements and no offset, so every grid planet but Earth was out of phase (Jupiter&#39;s window ~80 days early) while a hand-set Mars <code>L0</code> hid it for Mars and broke <code>/fly</code>&#39;s Mars;</li><li>the grids priced v∞ as if Earth and the target moved tangentially at circular speed — with eccentric planets Mars alone has up to ~2 km/s of radial motion.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>The JPL ephemeris is the reference.</strong> <code>planet-positions-jpl.test.ts</code> requires every planet and Earth within 0.6° of it, 1970–2035; <code>porkchop-windows.test.ts</code> requires each Venus / Mars / Jupiter porkchop window within weeks of the JPL Hohmann phase date, Δv near Hohmann. <code>scripts/fly/planet-model-check.ts</code>, <code>blueprint-fit-audit.ts</code> and <code>porkchop-window-check.ts</code> print the tables.</li><li><strong>Planets and Earth carry their eccentricity</strong> (<code>e</code>, <code>ϖ</code> from <code>planets.json</code>): <code>buildPlanetDestination</code> and <code>EARTH_ORBIT</code>. Max error is now 0.47° (Mercury), Earth 0.02°. <code>marsPos</code> delegates to <code>destinationPos</code>. Bodies below the convergence concern of ADR-028 (Ceres, Arrokoth) stay circular.</li><li><strong>Grid epoch.</strong> <code>HELIO_GRID_EPOCH_SIM_DAY</code> (9497 = 2026-01-01 from J2000) is added before any grid places a body. Mars <code>L0</code> is JPL&#39;s J2000 value again.</li><li><strong>Lambert, prograde.</strong> <code>solveLambertPrograde</code> picks the long way when the transfer angle exceeds 180° and falls back to the high branch, so slow inner-planet transfers solve.</li><li><strong>Vector v∞ at both ends.</strong> <code>helio-state.ts</code>: <code>bodyHelioXY</code> (the shared position model), <code>bodyHelioVelXY</code> (velocity), <code>lambertEndVelocities</code> (Lagrange f/g vectors at r1, r2 from the solver&#39;s <code>p</code>). Both grids take <code>|v_transfer − v_body|</code> at departure and arrival.</li><li><strong>Drawn orbits follow the model.</strong> <code>/fly</code> rings (3D and the 2D fallback) are traced from <code>orbitPath</code> / <code>earthOrbitPath</code>, so a body sits on its ring on every day.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Porkchops and <code>/fly</code> paths were regenerated (<code>npm run precompute-porkchops</code>, <code>generate-fly-trajectory.ts</code> for every file in <code>static/data/fly-trajectories/</code>). Windows: Venus, Jupiter, Saturn within 1–10 days of the JPL phase dates; Mars 2026 minimum 2026-10-30 (NASA&#39;s handbook lowest-energy departures Oct 31 / Nov 14; it was 11-12).</li><li>Tests that encoded circles changed: Ceres for the circular-ring case, radius bounds for Mars and Earth, the soundness check compares the arc end at <code>flyby_day</code>, the fast moon-transfer guard at 1.4 yr (1.2 yr from day 280 now needs a hyperbola the elliptic solver does not produce; the guard still fails on a scalar v∞).</li><li>The <code>/fly</code> HUD&#39;s transfer ellipse reaches the target&#39;s real radius at arrival; the render-state hook exposes it (<code>data-transfer-a-au</code>) for the e2e vis-viva check.</li><li>Any change to the elements, the epoch or the solver re-runs the three checks above and regenerates the porkchops and <code>/fly</code> paths.</li></ul>',9)])])}const f=o(s,[["render",n]]);export{u as __pageData,f as default};
